										</figure>
									</div>
				</div>
				<div class="elementor-element elementor-element-42c9c07 elementor-widget elementor-widget-image" data-id="42c9c07" data-element_type="widget" data-widget_type="image.default">
				<div class="elementor-widget-container">
												<figure class="wp-caption">
										<img loading="lazy" decoding="async" width="590" height="332" src="https://media.huynhhieutravel.com/email-da-chinh-sua.jpg" class="attachment-medium_large size-medium_large wp-image-7276" alt="Email đã chỉnh sửa" />											<figcaption class="widget-image-caption wp-caption-text">Email đã chỉnh sửa</figcaption>
